SELECT sr.sr_ticket_number, sr.sr_return_quantity, (sr.sr_return_amt + sr.sr_return_tax) AS total_return_amt, (sr.sr_return_amt * 35.14) AS scaled_return_amt, CASE WHEN sr.sr_return_quantity > 80 THEN 'High' ELSE 'Low' END AS quantity_category, r.r_reason_desc, CASE WHEN r.r_reason_desc = 'reason 29                                                                                           ' THEN 1 ELSE 0 END AS is_specific_reason FROM store_returns sr JOIN reason r ON sr.sr_reason_sk = r.r_reason_sk WHERE sr.sr_returned_date_sk = 2450924
